mapper.select:
SELECT last_read_message_id
FROM im_user_inbox
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

SELECT user_id, conversation_id, unread_count, last_read_message_id, last_message_id,
       last_content, last_time, pinned, muted, updated_at
FROM im_user_inbox
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

SELECT COALESCE(SUM(unread_count), 0)
FROM im_user_inbox
WHERE user_id = #{userId}

mapper.update:
UPDATE im_user_inbox
SET unread_count = 0,
    last_read_message_id = GREATEST(last_read_message_id, #{lastId}),
    updated_at = NOW()
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

UPDATE im_user_inbox
SET last_content = LEFT(#{preview}, 256),
    updated_at = NOW()
WHERE conversation_id = #{conversationId}
  AND last_message_id = #{messageId}

UPDATE im_user_inbox
SET muted = #{muted},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

mapper.delete:
DELETE FROM im_user_inbox
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
